onload = () => {
  document.body.classList.remove("container");
};

// En el celular 100vh incluye las barras del navegador y tapa lo de abajo:
// se usa la altura realmente visible.
function ajustarAlto() {
  document.documentElement.style.setProperty("--alto", window.innerHeight + "px");
}
ajustarAlto();
window.addEventListener("resize", ajustarAlto);

// Canción (primeros 40 segundos) incluida dentro del código, no depende de carpetas
const CANCION_B64 = "";

function base64ABlobUrl(b64, tipo) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return URL.createObjectURL(new Blob([bytes], { type: tipo }));
}

const botonPlay = document.getElementById("btn-play");
const cancion = document.getElementById("cancion");
cancion.src = base64ABlobUrl(CANCION_B64, "audio/mpeg");

botonPlay.addEventListener("click", () => {
  document.body.classList.add("playing");
  cancion.currentTime = 0;
  cancion.play().catch((err) => console.error("No se pudo reproducir:", err));
});
